const items = $input.all();

// Raw request body (used to detect missing / non-numeric financial inputs before Edit Fields converts them).
// Webhook runs read the Webhook body; manual runs read the Sample Product Input body.
const readBody = (nodeName) => {
  try {
    const n = $(nodeName).first();
    if (n && n.json && n.json.body && typeof n.json.body === "object") return n.json.body;
  } catch (e) {}
  return null;
};
const rawBody = readBody("Webhook") || readBody("Sample Product Input");

// ISO 4217 currency codes (no exchange-rate conversion is ever applied).
const ISO_CURRENCIES = new Set(("AED AFN ALL AMD ANG AOA ARS AUD AWG AZN BAM BBD BDT BGN BHD BIF BMD BND BOB BRL BSD BTN BWP BYN BZD " +
  "CAD CDF CHF CLP CNY COP CRC CUP CVE CZK DJF DKK DOP DZD EGP ERN ETB EUR FJD FKP GBP GEL GHS GIP GMD GNF GTQ GYD " +
  "HKD HNL HTG HUF IDR ILS INR IQD IRR ISK JMD JOD JPY KES KGS KHR KMF KPW KRW KWD KYD KZT LAK LBP LKR LRD LSL LYD " +
  "MAD MDL MGA MKD MMK MNT MOP MRU MUR MVR MWK MXN MYR MZN NAD NGN NIO NOK NPR NZD OMR PAB PEN PGK PHP PKR PLN PYG " +
  "QAR RON RSD RUB RWF SAR SBD SCR SDG SEK SGD SHP SLE SLL SOS SRD SSP STN SVC SYP SZL THB TJS TMT TND TOP TRY TTD " +
  "TWD TZS UAH UGX USD UYU UZS VES VND VUV WST XAF XCD XCG XOF XPF YER ZAR ZMW ZWG ZWL").split(" "));

const isBlank = (v) => v === undefined || v === null || String(v).trim() === "";

const FINANCIAL_RULES = [
  { field: "planned_selling_price", label: "planned_selling_price", mustBePositive: true },
  { field: "expected_sales_quantity", label: "expected_sales_quantity", mustBePositive: true },
  { field: "estimated_unit_cost", label: "estimated_unit_cost", mustBePositive: false },
  { field: "planned_marketing_budget", label: "planned_marketing_budget", mustBePositive: false }
];

return items.map((item) => {
  // Webhook input ke body se data lo.
  // Agar input pehle se flat hai, toh use directly use karo.
  const data = item.json.body ?? item.json;

  const requiredFields = [
    "product_name",
    "product_category",
    "target_market",
    "currency",
    "decision_type",
    "launch_stage"
  ];

  const missingFields = requiredFields.filter((field) => isBlank(data[field]));
  const invalidFields = [];
  const errors = [];

  missingFields.forEach((field) => {
    errors.push({ field: field, message: field + " is required." });
  });

  // This workflow only supports pre-launch evaluation.
  if (!missingFields.includes("launch_stage")) {
    const stage = String(data.launch_stage).trim().toLowerCase();
    if (stage !== "pre_launch") {
      invalidFields.push("launch_stage");
      errors.push({
        field: "launch_stage",
        message: "launch_stage must be 'pre_launch' for this workflow (received '" + String(data.launch_stage) + "')."
      });
    }
  }

  // Currency must be a valid ISO 4217 code (case-insensitive)
  if (!missingFields.includes("currency")) {
    const cur = String(data.currency).trim().toUpperCase();
    if (!/^[A-Z]{3}$/.test(cur) || !ISO_CURRENCIES.has(cur)) {
      invalidFields.push("currency");
      errors.push({
        field: "currency",
        message: "currency must be a valid ISO 4217 code such as INR, USD, EUR, GBP, CNY, JPY or KRW (received '" + String(data.currency) + "')."
      });
    }
  }

  // Financial inputs
  const source = rawBody ?? data;
  const financials = {};

  FINANCIAL_RULES.forEach((rule) => {
    const raw = source[rule.field];

    if (isBlank(raw)) {
      missingFields.push(rule.field);
      errors.push({ field: rule.field, message: rule.label + " is required and must be a number." });
      return;
    }

    if (typeof raw !== "number" && typeof raw !== "string") {
      invalidFields.push(rule.field);
      errors.push({ field: rule.field, message: rule.label + " must be a finite number." });
      return;
    }

    const n = typeof raw === "string" ? Number(raw.trim()) : raw;

    if (!Number.isFinite(n)) {
      invalidFields.push(rule.field);
      errors.push({ field: rule.field, message: rule.label + " must be a finite number." });
    } else if (rule.mustBePositive && n <= 0) {
      invalidFields.push(rule.field);
      errors.push({ field: rule.field, message: rule.label + " must be greater than zero (received " + n + ")." });
    } else if (n < 0) {
      invalidFields.push(rule.field);
      errors.push({ field: rule.field, message: rule.label + " must be zero or greater (received " + n + ")." });
    } else {
      financials[rule.field] = n;
    }
  });

  const isValid = errors.length === 0;
  let message = "Product evaluation request is valid";
  if (!isValid) {
    message = invalidFields.length === 0
      ? "Required fields are missing"
      : "Validation failed: " + errors.map((e) => e.message).join(" ");
  }

  return {
    json: {
      ...data,
      ...financials,
      validation: {
        is_valid: isValid,
        missing_fields: missingFields,
        invalid_fields: invalidFields,
        errors: errors,
        message: message
      }
    }
  };
});

// Combine every Brave Search response into ONE item so the Research Agent runs once.
// Product fields are carried over from Research Input so the agent prompt keeps working.
const base = $("Research Input").first().json;
const queries = Array.isArray(base.search_queries) ? base.search_queries : [];
const strip = (s) => String(s ?? "").replace(/<[^>]+>/g, "").replace(/\s+/g, " ").trim();
const searches = [];
const seen = new Set();

$input.all().forEach((item, idx) => {
  const r = item.json || {};
  const query = strip((r.query && r.query.original) || queries[idx] || "");
  if (r.error) {
    searches.push({ query: query, status: "error", error: strip(r.error.message || r.error), results: [] });
    return;
  }
  const results = [];
  const add = (x, source) => {
    if (!x || !x.url || seen.has(x.url)) return;
    seen.add(x.url);
    const snippets = Array.isArray(x.extra_snippets) ? x.extra_snippets.map(strip).filter(Boolean).slice(0, 2) : [];
    results.push({
      title: strip(x.title),
      url: String(x.url),
      description: strip(x.description || x.answer || ""),
      extra_snippets: snippets,
      page_age: x.page_age || x.age || null,
      source_type: source
    });
  };
  ((r.web && r.web.results) || []).forEach((x) => add(x, "web"));
  ((r.news && r.news.results) || []).forEach((x) => add(x, "news"));
  ((r.faq && r.faq.results) || []).forEach((x) => add(x, "faq"));
  searches.push({ query: query, status: results.length ? "ok" : "no_results", results: results });
});

const totalResults = searches.reduce((n, s) => n + s.results.length, 0);
let text = "";
searches.forEach((s, i) => {
  text += "### Search " + (i + 1) + ": " + s.query + " [" + s.status + "]\n";
  if (s.status === "error") text += "Search failed: " + s.error + "\n";
  s.results.forEach((x, j) => {
    text += (j + 1) + ". " + x.title + "\n   URL: " + x.url + "\n";
    if (x.page_age) text += "   Date: " + x.page_age + "\n";
    if (x.description) text += "   Snippet: " + x.description + "\n";
    x.extra_snippets.forEach((e) => { text += "   Extra: " + e + "\n"; });
  });
  text += "\n";
});
if (!totalResults) text = "NO SEARCH RESULTS WERE RETRIEVED. Treat all external information as unavailable.";

return [{ json: Object.assign({}, base, {
  search_results: searches,
  search_results_text: text,
  search_result_count: totalResults,
  search_urls: searches.flatMap((s) => s.results.map((x) => x.url))
}) }];

const items = $input.all();

const round2 = (n) => Math.round(n * 100) / 100;

// External market factors: parse the structured JSON block the Research Agent (AI Agent) appends to its report.
// Qualitative intelligence only - it is NOT applied to any financial figure below.
const buildExternalMarketFactors = (input) => {
  const researchText = String($("AI Agent").first().json.output ?? "");
  const match = researchText.match(/<<<EXTERNAL_MARKET_FACTORS_JSON>>>([^]*?)<<<END_EXTERNAL_MARKET_FACTORS_JSON>>>/);
  const fence = String.fromCharCode(96, 96, 96);
  let parsed = null;
  let parseStatus = "not_found";
  if (match) {
    let candidate = match[1].split(fence + "json").join("").split(fence).join("").trim();
    const first = candidate.indexOf("{");
    const last = candidate.lastIndexOf("}");
    if (first >= 0 && last > first) candidate = candidate.slice(first, last + 1);
    try {
      parsed = JSON.parse(candidate);
      parseStatus = "parsed";
    } catch (e) {
      parseStatus = "invalid_json";
    }
  }
  const p = parsed && typeof parsed === "object" ? parsed : {};
  const str = (v, d) => (v === undefined || v === null || String(v).trim() === "") ? d : String(v);
  const arr = (v) => Array.isArray(v) ? v.filter((x) => x !== null && x !== undefined && String(x).trim() !== "").map(String) : [];
  const pick = (v, allowed, d) => { const s = String(v ?? "").trim().toLowerCase(); return allowed.includes(s) ? s : d; };
  const events = (Array.isArray(p.events) ? p.events : []).filter((e) => e && typeof e === "object").map((e) => ({
    event_name: str(e.event_name, "Unnamed factor"),
    event_type: str(e.event_type, "other"),
    country: str(e.country, input.target_market ?? "Not provided"),
    expected_period: str(e.expected_period, "Unknown"),
    affected_categories: arr(e.affected_categories),
    potential_demand_direction: pick(e.potential_demand_direction, ["positive", "negative", "mixed", "unknown"], "unknown"),
    potential_cost_impact: str(e.potential_cost_impact, "Unknown"),
    potential_supply_impact: str(e.potential_supply_impact, "Unknown"),
    evidence_summary: str(e.evidence_summary, "No evidence summary provided"),
    source_urls: arr(e.source_urls).filter((u) => /^https?:[/][/]/i.test(u)),
    confidence_level: pick(e.confidence_level, ["low", "medium", "high"], "low"),
    evidence_classification: pick(e.evidence_classification, ["verified_fact", "research_finding", "assumption"], "assumption")
  }));
  const scope = p.research_scope && typeof p.research_scope === "object" ? p.research_scope : {};
  const userPeriod = str(input.intended_launch_period, null);
  const limitations = arr(p.research_limitations);
  if (parseStatus !== "parsed") {
    limitations.push("Structured external factors could not be extracted from the research report (" + parseStatus + "); refer to the narrative research report.");
  }
  return {
    status: parseStatus === "parsed" ? "available" : "unavailable",
    parse_status: parseStatus,
    research_scope: {
      product_category: str(scope.product_category, input.product_category ?? "Not provided"),
      country: str(scope.country, input.target_market ?? "Not provided"),
      launch_period: str(scope.launch_period, userPeriod ?? "Not provided (assumed next 6 months)"),
      launch_period_basis: userPeriod ? "user_provided" : "assumed"
    },
    events: events,
    verified_facts: arr(p.verified_facts),
    research_findings: arr(p.research_findings),
    assumptions: arr(p.assumptions),
    overall_confidence: pick(p.overall_confidence, ["low", "medium", "high"], "low"),
    research_limitations: limitations,
    note: "Qualitative pre-launch intelligence from web research. Not applied to the deterministic financial calculations."
  };
};

return items.map(() => {
  // Risk Agent ka output
  const riskReport = $("RISK AGENT").first().json.output ?? "";

  // Original product details and validated financial inputs
  // Financial inputs come from Edit Fields (already validated by "Code in JavaScript").
  const input = $("Edit Fields").first().json;

  const price = Number(input.planned_selling_price);
  const rawQuantity = Number(input.expected_sales_quantity);
  const unitCost = Number(input.estimated_unit_cost);
  const marketingBudget = Number(input.planned_marketing_budget);

  // Products are sold in whole units: every quantity (baseline and scenarios) is rounded
  // to the nearest whole unit with Math.round, and all revenue/cost figures use that whole-unit quantity.
  const toUnits = (q) => Math.round(q);
  const quantity = toUnits(rawQuantity);

  const missingBaselineData = [
    ["planned_selling_price", price],
    ["expected_sales_quantity", rawQuantity],
    ["estimated_unit_cost", unitCost],
    ["planned_marketing_budget", marketingBudget]
  ].filter((pair) => !Number.isFinite(pair[1])).map((pair) => pair[0]);

  // Baseline
  const baselineRevenue = price * quantity;
  const baselineProductionCost = unitCost * quantity;
  const baselineTotalCost = baselineProductionCost + marketingBudget;
  const baselineProfit = baselineRevenue - baselineTotalCost;

  const scenarioDefs = [
    { name: "Base Case", demandChangePct: 0, priceChangePct: 0, marketingCostChangePct: 0 },
    { name: "Optimistic Case", demandChangePct: 15, priceChangePct: 0, marketingCostChangePct: 0 },
    { name: "Downside Case", demandChangePct: -15, priceChangePct: 0, marketingCostChangePct: 0 }
  ];

  const scenarios = scenarioDefs.map((sc) => {
    const scenarioQuantity = toUnits(quantity * (1 + sc.demandChangePct / 100));
    const scenarioRevenue = price * scenarioQuantity;
    const scenarioProductionCost = unitCost * scenarioQuantity;
    const scenarioTotalCost = scenarioProductionCost + marketingBudget;
    const scenarioProfit = scenarioRevenue - scenarioTotalCost;
    const margin = scenarioRevenue > 0 ? (scenarioProfit / scenarioRevenue) * 100 : null;

    return {
      name: sc.name,
      demand_change_pct: sc.demandChangePct,
      price_change_pct: sc.priceChangePct,
      marketing_budget_change_pct: sc.marketingCostChangePct,
      projected_quantity: scenarioQuantity,
      projected_revenue: round2(scenarioRevenue),
      production_cost: round2(scenarioProductionCost),
      marketing_budget: round2(marketingBudget),
      total_operating_cost: round2(scenarioTotalCost),
      estimated_profit: round2(scenarioProfit),
      profit_margin_pct: margin === null ? null : round2(margin),
      // Legacy keys kept for frontend compatibility
      demandChangePct: sc.demandChangePct,
      priceChangePct: sc.priceChangePct,
      marketingCostChangePct: sc.marketingCostChangePct,
      illustrativeRevenue: round2(scenarioRevenue),
      illustrativeOperatingCost: round2(scenarioTotalCost)
    };
  });

  const projectionNote =
    "These figures are illustrative pre-launch projections calculated deterministically from user-provided assumptions " +
    "(selling price, expected sales quantity, unit cost and marketing budget). They are not guaranteed forecasts, " +
    "not researched market data and not trained-model predictions.";

  return {
    json: {
      product_name: input.product_name ?? "Not provided",
      product_category: input.product_category ?? "Not provided",
      target_market: input.target_market ?? "Not provided",
      currency: input.currency ?? "Not provided",
      launch_stage: input.launch_stage ?? "Not provided",
      decision_type: input.decision_type ?? "Not provided",
      risk_report: riskReport,
      financial_inputs: {
        planned_selling_price: price,
        expected_sales_quantity: rawQuantity,
        estimated_unit_cost: unitCost,
        planned_marketing_budget: marketingBudget
      },
      baseline_quantity: quantity,
      baseline_revenue: round2(baselineRevenue),
      baseline_production_cost: round2(baselineProductionCost),
      baseline_marketing_budget: round2(marketingBudget),
      baseline_total_cost: round2(baselineTotalCost),
      baseline_profit: round2(baselineProfit),
      baseline_profit_margin_pct: baselineRevenue > 0 ? round2((baselineProfit / baselineRevenue) * 100) : null,
      scenarios,
      projection_note: projectionNote,
      assumptions: [
        "All financial inputs are user-provided pre-launch assumptions, not researched market evidence.",
        "Scenario demand changes (0%, +15%, -15%) are illustrative assumptions, not trained-model predictions.",
        "Selling price and marketing budget are held constant across all scenarios.",
        "Quantities are rounded to the nearest whole unit before revenue and cost are calculated.",
        "Total operating cost includes only production cost (unit cost x quantity) and the planned marketing budget.",
        "Costs not provided (e.g. fixed overheads, distribution, taxes, returns) are not included in these figures.",
        "External market factors are assessed qualitatively and are not applied to these figures."
      ],
      missing_baseline_data: missingBaselineData,
      external_market_factors: buildExternalMarketFactors(input)
    }
  };
});
